// §11 hardening defaults. Tunable per handler later; the caps are checked
// before dispatch so malformed or oversized input never reaches creator code.
const RATE_PER_S = 8
export const MAX_PAYLOAD_BYTES = 4096
// The call-site cap, checked BEFORE anything is sent. The transport drops a
// message over ~13 KB without a word, so an oversize send would otherwise
// vanish, burn its retries and reject as a timeout with nothing to pull on.
export const MAX_SEND_BYTES = 12_000
// Per-key state size guard: one SharedFact must stay far from the transport's
// 12 KB chunk edge. Warn, don't block — the creator may be mid-refactor.
const FACT_WARN_BYTES = 4096
// Per-key publish budget. setState is legal from a plain server update(), which
// is ~41 writes per key per second with nothing else in this path to stop them.
// Over budget the key stays dirty and publishes its NEWEST value once a token
// refills — coalescing, never dropping, so the last write always ships.
export const PUBLISH_PER_KEY_PER_S = 8
// §11.2: one player must not bloat the isolate or the Storage budget.
export const PLAYER_DATA_CAP_BYTES = 8192
// Zone verification (ported from zone-authority): positions arrive at ≤10 Hz
// and are the avatar's FEET while the real collider is a 2 m capsule, so an
// honest player standing on the boundary must not be called a cheat.
const ZONE_SLACK_M = 1
// A member whose position the server cannot see at all (still loading, comms
// hiccup) keeps their place this long before the sweep gives up on them.
const ZONE_LOST_GRACE_MS = 10_000
// Zone claims are edge-triggered by the client's own zone bus, so an honest
// player sends a couple per zone per visit; the sweep re-checks at 4 Hz anyway.
const ZONE_CLAIMS_PER_S = 4
// The pre-boot queues are fed by every client and drained only when boot ends,
// and the per-player rate limit lives PAST the gate — so unbounded they grow
// for as long as waking takes. The cap is generous next to a cold start (a
// client holds its own requests while the ladder says waking); over it the
// NEWEST is refused, which keeps the asks a player is actually waiting on.
export const MAX_PREBOOT_REQUESTS = 256
// One queue, two ends: the client parks a request while the ladder says waking,
// the server parks it until boot ends. Both are capped at MAX_PREBOOT_REQUESTS,
// and both answer a flood from here — a creator who reads either console is told
// the same thing, whichever end refused the ask.
export const WAKING_FLOOD_NAME = 'game.request:waking'
export const WAKING_FLOOD = `Over ${MAX_PREBOOT_REQUESTS} requests arrived while the server was waking, so the newest ones were dropped — call game.request once per player action, not every frame.`
export function wakingDropped(name: string): string {
  return `'${name}' was dropped while the server was waking — ask for it again once the server is running.`
}

export interface ZoneVolume {
  shape: 'box' | 'sphere'
  center: Vec3
  rotation: Quat
  scale: Vec3
}

// Same volume definition the engine uses (ADR-258): a UNIT box or sphere scaled
// by the entity's world transform; `slack` widens every half-extent by metres.
// The point moves into the volume's own frame (inverse rotation about the
// centre); scale stays in the half-extents, which keeps non-uniform scale exact.
function insideZone(volume: ZoneVolume, point: Vec3, slack: number): boolean {
  const { center, rotation, scale } = volume
  if (scale.x <= 0 || scale.y <= 0 || scale.z <= 0) return false
  const margin = slack > 0 ? slack : 0
  const half = { x: scale.x / 2 + margin, y: scale.y / 2 + margin, z: scale.z / 2 + margin }
  const inverse = { x: -rotation.x, y: -rotation.y, z: -rotation.z, w: rotation.w }
  const local = rotateVec(inverse, { x: point.x - center.x, y: point.y - center.y, z: point.z - center.z })
  if (volume.shape === 'sphere') {
    const x = local.x / half.x
    const y = local.y / half.y
    const z = local.z / half.z
    return x * x + y * y + z * z <= 1
  }
  return Math.abs(local.x) <= half.x && Math.abs(local.y) <= half.y && Math.abs(local.z) <= half.z
}

// The round tuple (§2.2): the numbers every client reconstructs a round from,
// plus the id real games key per-round validity on (§12 #2). It rides
// game.state under one reserved key, so a late joiner gets the current round
// from the snapshot like any other fact — no second mechanism.
//
// The number counts rounds inside ONE wake of the Multiplayer Server: state
// resets when the server sleeps (§5 lifetimes), so the count starts again at 1
// — which is why the id, and not the number, is what survives being written
// down. Same shape as the number for a reader ('k3f9x2-7'), and never twice.
const ROUND_STATE_KEY = 'round'

export interface RoundInfo {
  /** This round, once ever — `<wake>-<number>`. Compare it with ===, write it
   * down, print it. Two rounds never share one, not even across a sleep. */
  id: string
  /** 1, 2, 3… within this wake of the Multiplayer Server. The server sleeps
   * when the scene is empty and counts from 1 again when it wakes, so anything
   * kept past the round it belongs to — in game.saved, in game.playerData —
   * has to hold the id instead. */
  number: number
  seed: number
  phase: number
  phaseStartMs: number
  configVersion: number
}

function zeroRound(): RoundInfo {
  return { id: '', number: 0, seed: 0, phase: 0, phaseStartMs: 0, configVersion: 0 }
}

/** Defensive read: the tuple crossed the wire, and a creator can clobber the
 * reserved key — a corrupt field must not poison every derived layout. */
function asRoundInfo(value: unknown): RoundInfo {
  if (typeof value !== 'object' || value === null) return zeroRound()
  const record = value as Record<string, unknown>
  const read = (key: Exclude<keyof RoundInfo, 'id'>): number => {
    const raw = record[key]
    return typeof raw === 'number' && Number.isFinite(raw) ? Math.floor(raw) : 0
  }
  const number = read('number')
  const id = record.id
  // No id is no round: everything that keys on one would otherwise key on the
  // empty string and call two different rounds the same round.
  if (number <= 0 || typeof id !== 'string' || id === '') return zeroRound()
  return {
    id,
    number,
    seed: read('seed'),
    phase: read('phase'),
    phaseStartMs: read('phaseStartMs'),
    configVersion: read('configVersion')
  }
}

/** The tag every round id this wake carries: the instant the Multiplayer
 * Server woke, salted with the first seed it drew — so a wake cannot reuse the
 * one before it, and neither can the round numbers counted inside it. */
function wakeTag(nowMs: number, seed: number): string {
  return ((Math.imul(nowMs | 0, 0x9e3779b1) ^ seed) >>> 0).toString(36)
}

/** One rng stream per (round seed, prefab): two layouts sharing a round must
 * not share draws (the draw-order contract, rng.ts rule 1). */
export function layoutSeed(seed: number, prefab: string): number {
  let h = seed | 0
  for (let i = 0; i < prefab.length; i++) h = (Math.imul(h, 31) + prefab.charCodeAt(i)) | 0
  return h
}

// The Game Config version pinned into the tuple, published by the generated
// src/scripts/game-config.ts on globalThis — the only channel a carried module
// copy can read it through (the round-loop precedent).
function configVersionNow(): number {
  const bag = (globalThis as unknown as Record<string, unknown>).__dclGameConfig_v1
  const version = typeof bag === 'object' && bag !== null ? (bag as Record<string, unknown>).version : undefined
  return typeof version === 'number' && Number.isFinite(version) && version >= 0 ? Math.floor(version) : 0
}

